-- GuitarCare application accounts. Passwords are BCrypt hashes generated by the Spring Boot API.
create table if not exists public.app_users (
    id uuid primary key,
    full_name varchar(120) not null,
    email varchar(254) not null unique,
    password_hash varchar(100) not null,
    created_at timestamptz not null default now()
);

-- Application account data is accessed only through the Spring Boot backend using
-- the database connection string. Do not expose password_hash through the browser Data API.
alter table public.app_users enable row level security;
